import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmEditCurso = () => {
  const { id } = useParams(); // Obtém o ID do curso da URL
  const navigate = useNavigate(); // Hook para navegação

  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
  });

  // Buscar os dados do curso ao carregar a página
  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
        } else {
          console.error("Erro ao buscar curso");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchCurso();
  }, [id]);

  // Atualiza os valores do curso conforme o usuário altera os inputs
  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  // Enviar os dados atualizados para o backend
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(curso),
      });

      if (resposta.ok) {
        alert("Curso atualizado com sucesso!");
        navigate("/admlistcurso"); // Redireciona para a página de listagem
      } else {
        console.error("Erro ao atualizar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-center mt-4">
        <form
          className="bg-white p-4 rounded shadow"
          style={{ width: "400px" }}
          onSubmit={handleSubmit}
        >
          <h3 className="text-center">Editar Curso</h3>

          <input
            type="text"
            name="nome"
            className="form-control mb-3"
            placeholder="Nome"
            value={curso.nome}
            onChange={handleChange}
            required
          />

          <select
            name="nivel"
            className="form-control mb-3"
            value={curso.nivel}
            onChange={handleChange}
            required
          >
            <option value="">Selecione o nível</option>
            <option value="1">1</option>
            <option value="2">2</option>
            <option value="3">3</option>
          </select>

          <select
            name="periodo"
            className="form-control mb-3"
            value={curso.periodo}
            onChange={handleChange}
            required
          >
            <option value="">Selecione o período</option>
            <option value="Manha">Manhã</option>
            <option value="Tarde">Tarde</option>
          </select>

          <select
            name="area"
            className="form-control mb-3"
            value={curso.area}
            onChange={handleChange}
            required
          >
            <option value="">Selecione a área</option>
            <option value="Contabilidade">Contabilidade</option>
            <option value="Matematica">Matemática</option>
          </select>

          <div className="d-flex justify-content-between">
            <button
              type="button"
              className="btn btn-danger"
              onClick={() => navigate("/cursos")}
            >
              Cancelar
            </button>
            <button type="submit" className="btn btn-success">
              Salvar Alterações
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdmEditCurso;
